def solution(input_str):
    def process_input(input_str):
        lines = input_str.strip().split('\n')
        n, m = int(lines[0].split()[0]), int(lines[0].split()[1])
        offers = []
        for line in lines[1:]:
            if line:
                l, r = map(int, line.split())
                offers.append((l, r))
        return n, m, offers

    n, m, offers = process_input(input_str)

    results = []

    for x in range(1, n + 1):
        occupied = set()
        total_days = 0

        for l, r in offers:
            length = r - l + 1
            if length >= x:
                # Check if any day in [l, r] is already occupied
                is_overlapping = False
                for day in range(l, r + 1):
                    if day in occupied:
                        is_overlapping = True
                        break

                if not is_overlapping:
                    # Accept the offer
                    for day in range(l, r + 1):
                        occupied.add(day)
                    total_days += length

        results.append(total_days)

    return '\n'.join(map(str, results)) + '\n'


