def solution(input_str):
    data = input_str.strip().split('\n')
    if not data:
        return ''

    n, m = map(int, data[0].split())

    # Parse operations: store x as the raw value * 100000 for integer arithmetic
    ops = []
    for i in range(1, n + 1):
        t, x_prime, y = map(int, data[i].split())
        ops.append((t, x_prime, y))

    # first_reachable[j] = earliest operation index (1 to n) when we can first reach j bananas
    first_reachable = [-1] * (m + 1)

    # current_reach: set of banana counts reachable at current step, capped at m
    # Initially we have 0 bananas before any operations
    current_reach = {0}

    for step_idx in range(1, n + 1):
        t, x_prime, y = ops[step_idx - 1]
        # x = x_prime / 100000

        next_reach = set()

        # For each banana count reachable at current step, try all a times (0 to y)
        for v in current_reach:
            if v > m:
                continue

            # Try applying operation 0 times
            if v <= m:
                next_reach.add(v)
                if v > 0 and first_reachable[v] == -1:
                    first_reachable[v] = step_idx

            # Try applying operation 1 to y times
            for a in range(1, y + 1):
                if v > m * a:
                    continue

                if t == 1:
                    # Type 1: k := ceil(k + x) applied a times
                    # k_new = k + a * x = k + a * x_prime / 100000
                    # ceil(k + a * x_prime / 100000)
                    # = floor(k * 100000 + a * x_prime) / 100000 rounded up
                    value_with_scale = v * 100000 + a * x_prime
                    if value_with_scale % 100000 != 0:
                        new_val = (value_with_scale // 100000) + 1
                    else:
                        new_val = value_with_scale // 100000

                    if new_val <= m:
                        next_reach.add(new_val)
                        if first_reachable[new_val] == -1:
                            first_reachable[new_val] = step_idx

                else:
                    # Type 2: k := ceil(k * x) applied a times
                    # k_new = k * x^a = k * (x_prime / 100000)^a = k * x_prime^a / 100000^a
                    # ceil(k * x_prime^a / 100000^a) = floor((k * x_prime^a + 100000^a - 1) / 100000^a)
                    x_pow_a = x_prime ** a
                    denom = 100000 ** a
                    k_with_denom = v * x_pow_a
                    if k_with_denom % denom != 0:
                        new_val = (k_with_denom // denom) + 1
                    else:
                        new_val = k_with_denom // denom

                    if new_val <= m:
                        next_reach.add(new_val)
                        if first_reachable[new_val] == -1:
                            first_reachable[new_val] = step_idx

        current_reach = next_reach

    # Output banana counts from 1 to m
    return ' '.join(map(str, first_reachable[1:])) + '\n'

from functools import lru_cache

@lru_cache(maxsize=None)
def compute_grundy(n, k):
    """Compute Grundy number for a pile of size n with given k"""
    if n == 0:
        return 0

    # Option 1: Remove 1 cow
    reachable = {compute_grundy(n - 1, k)}

    # Option 2: Split if even
    if n % 2 == 0:
        half = n // 2
        if k % 2 == 1:
            # k is odd: XOR sum of k copies of G(half) = G(half)
            reachable.add(compute_grundy(half, k))
        else:
            # k is even: XOR sum of k copies = 0
            reachable.add(0)

    # Compute MEX
    mex = 0
    while mex in reachable:
        mex += 1
    return mex

def get_grundy_with_pattern(n, k):
    """Compute Grundy number with pattern detection for large n"""
    # For large n values, we need to detect the pattern
    # But first, let's compute some values to understand the pattern

    if n == 0:
        return 0

    # For k=1, the pattern is relatively simple
    if k == 1:
        if n % 4 == 0:
            return 1 if n > 4 else 0
        elif n % 4 == 1:
            return 2 if n > 4 else 1
        elif n % 4 == 2:
            return 3
        else:  # n % 4 == 3
            return 0 if n > 1 else 1

    # General case - pattern depends on how quickly it stabilizes
    # Compute values around n to find the pattern
    cache = {}

    def helper(m, k, memo):
        if m == 0:
            return 0
        if m <= 1000 and memo is None:
            return describe_grundy_cache(m, k)
        if m in cache:
            return cache[m]

        reachable = {helper(m - 1, k, memo)}
        if m % 2 == 0:
            half = m // 2
            if k % 2 == 1:
                reachable.add(helper(half, k, memo))
            else:
                reachable.add(0)

        mex = 0
        while mex in reachable:
            mex += 1
        cache[m] = mex
        return mex

    # For very large n, we need a smarter approach
    # The pattern eventually becomes periodic

    if k == 1:
        if n == 0:
            return 0
        if n == 1:
            return 1
        if n % 2 == 0:
            if n // 2 % 2 == 0:
                return 0
            return 2
        else:
            return 2 if (n - 1) // 2 % 2 == 0 else 1

    # For k > 1 and k is even, all even positions become 0
    if k % 2 == 0:
        # Even k makes G(2m) = 0 for large enough m
        if n == 0:
            return 0
        if n % 2 == 0:
            return 0
        # For odd n, G(2m+1) = 2*m % 3 for large m
        m = n // 2
        if m == 0:
            return 1
        if m < 4:
            # Small odd values
            if n == 1:
                return 1
            if n == 3:
                return 2
            if n == 5:
                return 2
        return (n - 1) % 3

    # For odd k > 1
    if k % 2 == 1:
        if n == 0:
            return 0
        if n % 2 == 0:
            m = n // 2
            if m == 0:
                return 0
            if m < 5:
                # Small even values
                if n == 2:
                    return 0
                if n == 4:
                    return 2
                if n == 6:
                    return 1
                return 1
            return m % 3
        else:
            m = n // 2
            if m == 0:
                return 1
            if m < 5:
                # Small odd values
                if n == 1:
                    return 1
                if n == 3:
                    return 2
                if n == 5:
                    return 2
                if n == 7:
                    return 3
                if n == 9:
                    return 0
            return m % 3


