    lines = input_str.strip().split('\n')

    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    adj = []
    for i in range(m):
        u, v = map(int, lines[2 + i].split())
        adj.append((u - 1, v - 1))  # Convert to 0-indexed

    # Get prime factorizations for each number
    prime_exponents = {}  # prime -> [exponent for each position 0..n-1]

    for i, num in enumerate(a):
        temp = num
        p = 2
        while p * p <= temp:
            if temp % p == 0:
                count = 0
                while temp % p == 0:
                    count += 1
                    temp //= p
                if p not in prime_exponents:
                    prime_exponents[p] = [0] * n
                prime_exponents[p][i] = count
            p += 1
        if temp > 1:
            if temp not in prime_exponents:
                prime_exponents[temp] = [0] * n
            prime_exponents[temp][i] += 1

    total_ops = 0
    for p, exponents in prime_exponents.items():
        for u, v in adj:
            total_ops += min(exponents[u], exponents[v])

    return str(total_ops) + '\n'


