            # b in left subtree of a => b < a in inorder
            they_must_be_before[a].append(b)
        else:  # RIGHT
            # b in right subtree of a => b > a in inorder
            they_must_be_after[a].append(b)

    # Topological sort based on "before" constraints
    in_degree = [0] * (n + 1)
    for u in range(1, n + 1):
        for v in they_must_be_before[u]:
            in_degree[u] += 1

