def solution(input_str: str) -> str:
    """
    Solution for the BubbleReactor problem.

    The problem asks us to maximize the sum of potentials when starting nodes in a graph.
    - N nodes with N edges (one cycle structure)
    - Start one node manually, then others when their neighbor is started
    - Potential of a node = number of inactive nodes it can power on (including itself)
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    adj = [[] for _ in range(n)]
    for i in range(1, n + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    def bfs_order(start):
        """Get BFS traversal order from start node"""
        visited = [False] * n
        order = []
        queue = [start]
        visited[start] = True
        while queue:
            u = queue.pop(0)
            order.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return order

    def component_size(inactive_set, node):
        """Count nodes in connected component containing node among inactive nodes"""
        if node not in inactive_set:
            return 0
        visited = set()
        stack = [node]
        while stack:
            u = stack.pop()
            if u in visited or u not in inactive_set:
                continue
            visited.add(u)
            for v in adj[u]:
                if v not in visited and v in inactive_set:
                    stack.append(v)
        return len(visited)

    def solve(start):
        """Calculate total potential sum when starting from node `start`"""
        order = bfs_order(start)
        activated = {start}
        total = 0

        for u in order:
            if u in activated:
                continue
            # Potential of u = 1 (itself) + inactive nodes connected to u through inactive nodes
            inactive = set(range(n)) - activated
            pot = component_size(inactive, u) + 1
            activated.add(u)
            total += pot

        return total

    best = 0
    for s in range(n):
        best = max(best, solve(s))

    return str(best)

