def combinations(iterable, length):
    pool = tuple(iterable)
    start = 0

    def helper(r, remaining):
        if r == 0:
            yield ()
        else:
            for i in range(start, len(pool) - remaining + 1):
                for t in helper(r - 1, remaining - 1):
                    yield (pool[i],) + t

    return list(helper(length, len(pool) - length)) if length > 0 else [()]

