def pow_mod(a, b, mod):
    result = 1
    while b > 0:
        if b & 1:
            result = result * a % mod
        a = a * a % mod
        b >>= 1
    return result

def inverse(n):
    return pow_mod(n % MOD, MOD - 2, MOD)

def solution(data):
