    size = 4005
    fact = [1] * size
    inv = [1] * size

    for i in range(1, size):
        fact[i] = fact[i - 1] * i % MOD

    inv[size - 1] = inverse(fact[size - 1])
    for i in range(size - 2, -1, -1):
        inv[i] = inv[i + 1] * (i + 1) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv[r] % MOD * inv[n - r] % MOD

    def C2n(n, r):
