        term = term * fact[j] % MOD
        term = term * fact[n - j] % MOD
        term = term * inverse(fact[n + 1]) % MOD
        total = (total + term) % MOD

    # Multiply by l
    l_mod = l % MOD
    total = total * l_mod % MOD

    return str(total)

