    if not lines:
        return '0'

    try:
        n, m = map(int, lines[0].split())
    except:
        return '0'

    attempts = []
    for i in range(1, m + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) < 2:
            continue
        binary = parts[0]
        try:
            response = int(parts[1])
        except:
            continue
        attempts.append((binary, response))

    count = 0

    def backtrack(pos, current_matches):
        nonlocal count

        if pos == n:
            # All positions filled, check if all constraints are satisfied
            valid = True
            for i in range(len(attempts)):
                if current_matches[i] != attempts[i][1]:
                    valid = False
                    break
            if valid:
                count += 1
            return

        for bit in ['0', '1']:
            # Create new matches state for this position
            new_matches = current_matches.copy()
            for i in range(len(attempts)):
                if attempts[i][0][pos] == bit:
                    new_matches[i] += 1

            # Pruning: check if this branch can possibly lead to a valid solution
            possible = True
            for i in range(len(attempts)):
                needed = attempts[i][1]
                current = new_matches[i]
                remaining = n - pos - 1
                max_possible = current + remaining

                # If we've already exceeded the needed matches, or 
                # can't possibly reach the needed matches
                if current > needed or max_possible < needed:
                    possible = False
                    break

            if possible:
                backtrack(pos + 1, new_matches)

    backtrack(0, [0] * len(attempts))

    return str(count)

def solution(input_str):
    a, b, n = map(int, input_str.strip().split())

    memo = {}

    def solve(current_a, current_b):
        state = (current_a, current_b)
        if state in memo:
            return memo[state]

        # Check if current state already loses (shouldn't happen if we check before making moves)
        # We test by computing current ways
        if current_a == 1:
            ways = 1
        else:
            # Use Python's built-in large number support
            ways = current_a ** current_b

        if ways >= n:
            memo[state] = "L"
            return "L"

        can_force_lose = False

        # Try increasing a
        if current_a + 1 <= 20000:
            next_a, next_b = current_a + 1, current_b
            if next_a == 1:
                next_ways = 1
            else:
                next_ways = next_a ** next_b
            if next_ways < n:
                if solve(next_a, next_b) == "L":
                    can_force_lose = True

        # If we've already found a winning move, no need to check further
        if can_force_lose:
            memo[state] = "W"
            return "W"

        # Try increasing b
        if current_b + 1 <= 1000:
            next_a, next_b = current_a, current_b + 1
            if next_a == 1:
                next_ways = 1
            else:
                next_ways = next_a ** next_b
            if next_ways < n:
                if solve(next_a, next_b) == "L":
                    can_force_lose = True

        result = "W" if can_force_lose else "L"
        memo[state] = result
        return result

    # Special handling for a=1
    # When a=1, 1^b = 1 for any b, so we need to add a boxes to grow past n
    if a == 1:
        # Check if 2^b >= n instantly
        try:
            if 2 ** b >= n:
                return "Missing\n\n"
        except OverflowError:
            return "Missing\n\n"

        # Check if we can compute with reasonable bounds
        # If b is very large, 2^b will definitely exceed 10^9
        if b > 60:  # 2^60 > 10^18 > 10^9
            return "Missing\n\n"

    result = solve(a, b)

    if result == "W":
        return "Masha\n\n"
    else:
        return "Stas\n\n"

