def solution(input_str):
    input_str = input_str.strip()
    if not input_str:
        return "YES\n"

    lines = input_str.split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    if n == 0:
        return "YES\n"

    # Map value to index for quick lookup
    num_to_idx = {val: i for i, val in enumerate(p)}

    # Build graph: connect numbers that must share the same set
    adj = [[] for _ in range(n)]
    for i in range(n):
        x = p[i]

        # Check a-x
        target_a = a - x
        if target_a in num_to_idx:
            j = num_to_idx[target_a]
            if i != j:
                adj[i].append(j)
                adj[j].append(i)

        # Check b-x
        target_b = b - x
        if target_b in num_to_idx:
            j = num_to_idx[target_b]
            if i != j:
                adj[i].append(j)
                adj[j].append(i)

    # Find connected components using BFS
    visited = [False] * n
    components = []

    for i in range(n):
        if not visited[i]:
            comp = []
            queue = [i]
            visited[i] = True
            while queue:
                node = queue.pop(0)
                comp.append(node)
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            components.append(comp)

    # Check each component and assign to set A or B
    comp_to_set = {}  # comp_index -> 0 for A, 1 for B

    for comp_idx, comp in enumerate(components):
        comp_values = {p[i] for i in comp}

        # Check if component can go to A
        can_to_A = True
        for x in comp_values:
            if (a - x) in num_to_idx:
                if (a - x) not in comp_values:
                    can_to_A = False
                    break

        # Check if component can go to B
        can_to_B = True
        for x in comp_values:
            if (b - x) in num_to_idx:
                if (b - x) not in comp_values:
                    can_to_B = False
                    break

        # If component cannot go to either set, impossible
        if not can_to_A and not can_to_B:
            return "NO"

        # Assign component to either set
        # Preferring A if both work, otherwise use whatever works
        if can_to_A:
            comp_to_set[comp_idx] = 0
        else:
            comp_to_set[comp_idx] = 1

    # Build output
    results = ['0'] * n
    for comp_idx, comp in enumerate(components):
        set_val = comp_to_set[comp_idx]
        for node_idx in comp:
            results[node_idx] = '1' if set_val == 1 else '0'

    return "YES\n" + ' '.join(results)

