    total_sets = a_wins + b_wins

    # Use greedy/iterative approach
    scores = []

    # Build one set at a time using local search

    for _ in range(total_sets):
        if a_wins == 0 and b_wins == 0:
            # All done
            break

        # Try constructing the next set
        if a_wins > 0:
            # Team A wins this set
