                b -= wins[1]
                a_wins -= 1
                continue

        if b_wins > 0:
            # Team B wins this set
            wins = find_valid_set_for_loss(a, b)
            if wins[0] is not None:
                scores.append(f"{wins[0]}:{wins[1]}")
                a -= wins[0]
                b -= wins[1]
                b_wins -= 1
                continue

    if a == 0 and b == 0:
        return " ".join(scores)

    return None

