def solution(input_str):
    n, k, m = map(int, input_str.split())
    MOD = 10**9 + 7

    if k == 1:
        return str(n)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count_ways(pos, steps_left, visited):
        if steps_left == 0:
            return 1

        total = 0
        upper = min(n, pos + m)
        for nxt in range(1, upper + 1):
            if nxt != pos and nxt not in visited:
                total = (total + count_ways(nxt, steps_left - 1, visited + (nxt,))) % MOD
        return total

    result = 0
    for start in range(1, n + 1):
        result = (result + count_ways(start, k - 1, (start,))) % MOD

    return str(result)
